function getTimeSlotLabel(timeSlot: string): string {
  const slots: Record<string, string> = {
    'morning': '🌅 Mattina',
    'afternoon': '🌇 Pomeriggio',
    'evening': '🌙 Serale',
    'full_day': '☀️ Giornata Intera'
  }
  return slots[timeSlot] || timeSlot
}

