export async function sendBookingConfirmation(bookingData: BookingEmailData) {
  try {
    const htmlContent = generateBookingConfirmationHTML(bookingData)

    const { data, error } = await resend.emails.send({
      from: 'NS3000 Rent <booking@rentsalernoboat.it>',
      to: [bookingData.customer.email],
      subject: `✅ Conferma Prenotazione ${bookingData.booking_number} - NS3000 Rent`,
      html: htmlContent,
    })

    if (error) {
      console.error('❌ Errore invio email:', error)
      throw new Error(error.message)
    }

    console.log('✅ Email inviata con successo:', data?.id)
    return { success: true, emailId: data?.id }
  } catch (error: any) {
    console.error('❌ Errore sendBookingConfirmation:', error)
    throw error
  }
}